add_action( 'woocommerce_before_quantity_input_field', 'perfectpixel_qty_minus_button' );
add_action( 'woocommerce_after_quantity_input_field', 'perfectpixel_qty_plus_button' );
add_action( 'wp_footer', 'perfectpixel_qty_buttons_script' );

function perfectpixel_qty_minus_button() {
	echo '<button type="button" class="perfectpixel-qty-btn minus" aria-label="−">−</button>';
}

function perfectpixel_qty_plus_button() {
	echo '<button type="button" class="perfectpixel-qty-btn plus" aria-label="+">+</button>';
}

function perfectpixel_qty_buttons_script() {
	if ( ! function_exists( 'is_woocommerce' ) || ! ( is_product() || is_cart() ) ) {
		return;
	}
	?>
	<style>.perfectpixel-qty-btn{min-width:2.2em;cursor:pointer}.quantity{display:inline-flex;align-items:center;gap:.25em}</style>
	<script>
	document.addEventListener( 'click', function ( e ) {
		var btn = e.target.closest( '.perfectpixel-qty-btn' );
		if ( ! btn ) {
			return;
		}
		var input = btn.parentNode.querySelector( 'input.qty' );
		if ( ! input ) {
			return;
		}
		var step = parseFloat( input.step ) || 1;
		var min = input.min !== '' ? parseFloat( input.min ) : 0;
		var max = input.max !== '' ? parseFloat( input.max ) : Infinity;
		var val = parseFloat( input.value ) || 0;
		val = btn.classList.contains( 'plus' ) ? Math.min( max, val + step ) : Math.max( min, val - step );
		input.value = val;
		input.dispatchEvent( new Event( 'change', { bubbles: true } ) );
		var update = document.querySelector( 'button[name="update_cart"]' );
		if ( update ) {
			update.disabled = false;
		}
	} );
	</script>
	<?php
}
